/**
 * Entity-name slug normalization — SINGLE SOURCE OF TRUTH.
 *
 * All slug logic for ingest pipelines lives in this module. Do not define
 * local slugify() functions in sync scripts — import one of these.
 *
 * THREE variants exist because stored slugs in `entities` were generated by
 * historically different implementations, and slugs are URL identity (and the
 * ingest dedup key for CIF-less rows). Changing any variant's behavior
 * re-keys existing entities. Divergence measured against a large set of
 * entity names:
 *
 *   - slugifyGrants → slugify (institutional): 7,547 names diverge (1.45%),
 *     5,109 of them into brand-new slugs (entity splits).
 *   - slugifyContracts → institutional: 2,805 names diverge (0.54%).
 *   - Abbreviation expansion misfires on company names ("MAT. CONS. ..." =
 *     Construccions → CONSORCI; "INST HOSPITALARIA" = instalación → INSTITUT),
 *     so it must never be applied to grants/contracts beneficiary names.
 *
 * Behavioral unification therefore requires a deliberate re-slug + merge data
 * change — NOT a code-only change. Until then, each pipeline keeps its
 * frozen behavior, verified bit-for-bit by tests/unit/slugify.test.ts.
 */

const DOTTED_SUFFIXES: [RegExp, string][] = [
  [/\bS\.\s*A\.\s*U\b\.?/g, "SAU"],
  [/\bS\.\s*A\b\.?/g, "SA"],
  [/\bS\.\s*L\.\s*U\b\.?/g, "SLU"],
  [/\bS\.\s*L\b\.?/g, "SL"],
  [/\bS\.\s*C\.\s*C\.\s*L\b\.?/g, "SCCL"],
  [/\bS\.\s*C\.\s*P\b\.?/g, "SCP"],
  [/\bS\.\s*C\b\.?/g, "SC"],
];

const SPACED_SUFFIXES: [RegExp, string][] = [
  [/\bS\s+A\s+U\b/g, "SAU"],
  [/\bS\s+A\b/g, "SA"],
  [/\bS\s+L\s+U\b/g, "SLU"],
  [/\bS\s+L\b/g, "SL"],
  [/\bS\s+C\s+C\s+L\b/g, "SCCL"],
  [/\bS\s+C\s+P\b/g, "SCP"],
  [/\bS\s+C\b/g, "SC"],
];

const ABBREVIATIONS: [RegExp, string][] = [
  [/\bAJUNT\b\.?\s*/g, "AJUNTAMENT "],
  [/\bAJ\b\.?\s*/g, "AJUNTAMENT "],
  [/\bDIPUT\b\.?\s*/g, "DIPUTACIO "],
  [/\bCONS\b\.?\s*/g, "CONSORCI "],
  [/\bFUND\b\.?\s*/g, "FUNDACIO "],
  [/\bUNIV\b\.?\s*/g, "UNIVERSITAT "],
  [/\bINST\b\.?\s*/g, "INSTITUT "],
  [/\bHOSP\b\.?\s*/g, "HOSPITAL "],
  [/\bASSOC\b\.?\s*/g, "ASSOCIACIO "],
];

function base(name: string): string {
  return name
    .toUpperCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, ""); // strip diacritics
}

function applyAll(s: string, rules: [RegExp, string][]): string {
  for (const [re, sub] of rules) s = s.replace(re, sub);
  return s;
}

function finalize(s: string): string {
  return s.replace(/[^A-Z0-9]+/g, "-").replace(/^-|-$/g, "");
}

/**
 * Institutional slugify — abbreviation expansion + dotted corporate suffixes.
 * ONLY for public-sector / institutional name sources where abbreviated forms
 * ("AJUNT.", "DIPUT.") are the norm and must fold into the canonical entity.
 * Mirrored in SQL by slugify_organ() (sql/schema/020-functions.sql); the
 * loaders of this repository use the two frozen variants below.
 */
export function slugify(name: string): string {
  return finalize(applyAll(applyAll(base(name), ABBREVIATIONS), DOTTED_SUFFIXES));
}

/**
 * Grants-pipeline slugify (RAISC) — dotted corporate suffixes only.
 * Frozen: matches the historical raisc-helpers implementation that generated
 * the slugs stored for grant beneficiaries.
 * Used by: src/lib/raisc-helpers.ts (re-export).
 */
export function slugifyGrants(name: string): string {
  return finalize(applyAll(base(name), DOTTED_SUFFIXES));
}

/**
 * Contracts-pipeline slugify (contractes.cat) — dotted + space-separated
 * corporate suffixes ("S A U" → SAU), no abbreviation expansion.
 * Frozen: matches the historical sync-contractes inline implementation.
 * Used by: sync-contractes.ts.
 */
export function slugifyContracts(name: string): string {
  return finalize(applyAll(applyAll(base(name), DOTTED_SUFFIXES), SPACED_SUFFIXES));
}
